'use strict';
(() => {
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num = value => Number.isFinite(Number(value)) ? Number(value) : 0;
  const safeUrl = value => { try { const u = new URL(value, location.href); return /^https?:$/.test(u.protocol) ? u.href : '#'; } catch { return '#'; } };
  const integer = value => new Intl.NumberFormat('en-US', {maximumFractionDigits:0}).format(num(value));
  const money = (value, compact = true) => new Intl.NumberFormat('en-US', {style:'currency', currency:'USD', notation:compact ? 'compact':'standard', maximumFractionDigits:compact ? 2:2}).format(num(value));
  const pct = (value, digits = 1) => value == null || !Number.isFinite(Number(value)) ? 'Unavailable' : `${(Number(value) * 100).toFixed(digits)}%`;
  const dec = (value, digits = 0) => value == null || !Number.isFinite(Number(value)) ? 'Unavailable' : Number(value).toLocaleString('en-US',{maximumFractionDigits:digits,minimumFractionDigits:digits});
  const sum = (rows, field) => rows.reduce((a,r) => a + num(typeof field === 'function' ? field(r) : r[field]), 0);
  const groupBy = (rows, key) => rows.reduce((a,r) => { const k=typeof key==='function'?key(r):r[key]; (a[k] ||= []).push(r); return a; }, {});
  const get = (obj, keys, fallback) => { for (const key of keys) if (obj?.[key] != null) return obj[key]; return fallback; };
  const fmtDate = value => { if (!value) return 'Not reported'; const d = new Date(`${String(value).slice(0,10)}T12:00:00Z`); return Number.isNaN(d.valueOf()) ? String(value) : new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(d); };
  const titleCase = value => String(value || '').replaceAll('_',' ').replace(/\b\w/g, x=>x.toUpperCase());
  const state = {year:'all',tab:'overview',search:'',page:1,pageSize:15,selectedAward:null,selectedRecipient:null,scenario:{},data:null,linkage:null,cases:[],reports:null};
  const tabs = {overview:{title:'Public money.<br><em>A clearer picture.</em>',description:'Follow contract funding to its recipients, compare like-for-like peers, and see which conclusions survive ambiguity.',label:'Overview'},explorer:{title:'Follow the<br><em>funding trail.</em>',description:'Move from the agency to an award, then inspect the transaction history and the recipient behind it.',label:'Money explorer'},uncertainty:{title:'How certain is<br><em>the conclusion?</em>',description:'Reliable identifiers come first. Where identity is ambiguous, test whole, consistent entity groupings before making a decision.',label:'Entity uncertainty'},cases:{title:'Three questions.<br><em>A trail of evidence.</em>',description:'Read the finding, inspect its denominator, and consider the ordinary explanations before deciding what to review.',label:'Case studies'},methods:{title:'Open the<br><em>working papers.</em>',description:'Definitions, queries, provenance, and limits. An analysis is useful when someone else can reproduce and challenge it.',label:'Methods & evidence'}};
  const metricDefs = {
    net:{title:'Net obligations',formula:'Σ federal_action_obligation for all transactions in the selected fiscal-year cohort, including negative values.',sql:'SELECT fiscal_year, SUM(obligation) AS net_obligations\nFROM fact_transactions\nWHERE fiscal_year = :fiscal_year\nGROUP BY fiscal_year;',caveat:'Obligations are legally binding commitments. They are not cash outlays, award ceilings, or the sum of repeated award summaries. Negative obligations can reflect legitimate cancellations, adjustments, and closeouts.'},
    awards:{title:'Distinct awards',formula:'COUNT(DISTINCT award_id) among selected transactions. An award can have many modifications and can appear in several fiscal years.',sql:'SELECT COUNT(DISTINCT award_id) AS awards\nFROM fact_transactions\nWHERE fiscal_year = :fiscal_year;',caveat:'An award count does not measure contracts newly signed in the year. Existing awards with modifications are included.'},
    recipients:{title:'Identified recipients',formula:'COUNT(DISTINCT recipient_id) among selected transactions. Prefer UEI, then source identifier, then an explicitly unresolved record key.',sql:'SELECT COUNT(DISTINCT recipient_id) AS recipients\nFROM fact_transactions\nWHERE fiscal_year = :fiscal_year;',caveat:'Different legal recipients can share a parent company. A name is not a reliable unique identifier. Grouping by parents answers a different concentration question.'},
    hhi:{title:'Supplier concentration · HHI',formula:'HHI = 10,000 × Σ (supplier positive-net share)². First sum signed obligations by recipient in the selected window; use max(recipient net balance,0) as the concentration weight.',sql:'WITH suppliers AS (\n  SELECT recipient_id, GREATEST(SUM(obligation), 0) AS positive\n  FROM fact_transactions WHERE fiscal_year = :fiscal_year\n  GROUP BY recipient_id\n), shares AS (\n  SELECT positive / SUM(positive) OVER () AS share FROM suppliers\n)\nSELECT 10000 * SUM(share * share) AS hhi FROM shares;',caveat:'Concentration is descriptive. It can reflect specialized requirements, framework vehicles, or a narrow cohort. It is not a finding about misconduct. HHI ranges from 0 to 10,000 for nonnegative shares.'},
    competition:{title:'Reported competition',formula:'Transaction counts by source competition classification. Missing or unknown codes remain a separate denominator category.',sql:"SELECT CASE WHEN competition_code IN ('A','D','F') THEN 'competed'\n WHEN competition_code IN ('B','C','G','NDO') THEN 'noncompetitive'\n ELSE 'unknown' END AS status, COUNT(*) AS transactions\nFROM fact_transactions\nWHERE fiscal_year = :fiscal_year\nGROUP BY status;",caveat:'Reported competition is an administrative field, not a reconstruction of bids. Modifications often inherit award characteristics. A noncompetitive action may have lawful statutory justification.'},
    yearend:{title:'September share',formula:'Positive obligations dated in September ÷ positive obligations in the selected fiscal-year cohort.',sql:'SELECT fiscal_year,\n  SUM(CASE WHEN MONTH(action_date)=9 THEN GREATEST(obligation,0) ELSE 0 END)\n  / NULLIF(SUM(GREATEST(obligation,0)),0) AS september_share\nFROM fact_transactions GROUP BY fiscal_year;',caveat:'Fiscal years end September 30. Budget timing, planned renewals, reporting delays, and program schedules can explain a September peak. Timing alone does not establish waste or wrongdoing.'},
    annual:{title:'Annual obligations',formula:'Net transaction obligations grouped by federal fiscal year (October 1 through September 30).',sql:'SELECT fiscal_year, SUM(obligation) AS net_obligations,\n  SUM(GREATEST(obligation,0)) AS positive_obligations,\n  SUM(LEAST(obligation,0)) AS deobligations\nFROM fact_transactions GROUP BY fiscal_year ORDER BY fiscal_year;',caveat:'A fiscal-year trend mixes award starts, continuing work, modifications, and deobligations. No causal claim follows from this descriptive time series.'},
    peers:{title:'Peer-group comparison',formula:'Compare within the selected fiscal-year window and the first three digits of the reported NAICS industry code. Compute positive-net recipient shares within each peer group.',sql:'WITH suppliers AS (\n SELECT fiscal_year, LEFT(naics,3) AS naics, recipient_id,\n GREATEST(SUM(obligation),0) AS positive\n FROM fact_transactions GROUP BY ALL\n), shares AS (\n SELECT *, positive / SUM(positive) OVER (PARTITION BY fiscal_year,naics) AS share\n FROM suppliers\n)\nSELECT fiscal_year, naics, COUNT(*) AS recipients,\n 10000*SUM(share*share) AS hhi\nFROM shares GROUP BY fiscal_year,naics;',caveat:'NAICS categories are broad industry labels, not fully interchangeable markets. Small peer groups produce unstable comparisons. Size, technical specialization, and contract vehicles can explain differences.'},
    top:{title:'Recipient funding shares',formula:'For each recipient, sum signed transaction obligations, take max(net balance,0), then divide by the sum of positive recipient net balances. Negative adjustments remain in every net total.',sql:'SELECT recipient_id, ARG_MAX(recipient_name,action_date) AS recipient_name,\n SUM(obligation) AS net_obligations,\n GREATEST(SUM(obligation),0) AS concentration_weight,\n COUNT(DISTINCT award_id) AS awards\nFROM fact_transactions\nWHERE fiscal_year = :fiscal_year\nGROUP BY recipient_id\nORDER BY concentration_weight DESC;',caveat:'Large totals are not a risk ranking. Prime recipients may contract with other organizations, and the data do not measure ultimate economic benefit.'},
    flow:{title:'Agency → award → recipient',formula:'Selected agency transaction obligations are grouped by award_id and attributed to the recipient reported on each action. Award summary totals are never added across modifications.',sql:'SELECT agency_name, award_id, recipient_id,\n SUM(obligation) AS net_obligations, COUNT(*) AS actions\nFROM fact_transactions\nWHERE fiscal_year = :fiscal_year\nGROUP BY agency_name,award_id,recipient_id;',caveat:'The explorer shows prime-award commitments for the bounded cohort. It does not show all government spending, cash paid, or complete subcontracting relationships.'}
  };
  function normalise(raw) {
    const meta = raw.meta || raw.metadata || raw.scope || {};
    let tx = raw.transactions || raw.fact_transactions || [];
    tx = tx.map((r,i) => ({...r,transaction_id:get(r,['transaction_id','id','transaction_unique_id'],`row-${i}`),award_id:String(get(r,['award_id','generated_unique_award_id','award_unique_id','generated_internal_id'],'')),recipient_id:String(get(r,['recipient_id','recipient_uei','uei','recipient_unique_id'],get(r,['recipient_name','name'],`unresolved-${i}`))),recipient_name:get(r,['recipient_name','recipient','name'],'Unreported recipient'),action_date:get(r,['action_date','date','Action Date'],null),fiscal_year:num(get(r,['fiscal_year','fy'],0)),obligation:num(get(r,['obligation','federal_action_obligation','transaction_amount','federal_action_obligated'],0)),competition:get(r,['competition','extent_competed','extent_competed_code'],null),offers_received:get(r,['offers_received','number_of_offers_received'],null),naics:get(r,['naics','naics_code'],'Unreported'),description:get(r,['description','award_description'],'No description reported'),source_url:safeUrl(get(r,['source_url','url'],`https://www.usaspending.gov/award/${encodeURIComponent(get(r,['award_id','generated_unique_award_id'],''))}`))}));
    const grouped = groupBy(tx,'award_id');
    let awards = raw.awards || raw.award_summaries || [];
    if (!awards.length) awards=Object.entries(grouped).map(([id,rows])=>({award_id:id,recipient_id:rows.at(-1).recipient_id,recipient_name:rows.at(-1).recipient_name,description:rows.at(-1).description,source_url:rows.at(-1).source_url,net_obligations:sum(rows,'obligation'),transaction_count:rows.length}));
    awards=awards.map(r=>({...r,award_id:String(get(r,['award_id','id','generated_unique_award_id'],'')),recipient_id:String(get(r,['recipient_id','recipient_uei','uei'],'unknown')),recipient_name:get(r,['recipient_name','recipient'],'Unreported recipient'),piid:get(r,['piid','award_id_piid','award_number'],get(r,['award_id','id'],'')),description:get(r,['description','award_description'],'No description reported'),net_obligations:num(get(r,['net_obligations','obligations','total_obligation'],0)),transaction_count:num(get(r,['transaction_count','transactions','actions'],grouped[String(get(r,['award_id','id'],''))]?.length||0)),source_url:safeUrl(get(r,['source_url','url'],`https://www.usaspending.gov/award/${encodeURIComponent(get(r,['award_id','id'],''))}`))}));
    const years=[...new Set(tx.map(r=>r.fiscal_year).filter(Boolean))].sort((a,b)=>a-b);
    return {...raw,meta,transactions:tx,awards,years,annual:raw.annual||raw.annual_summary||[]};
  }
  function selectedTx() { return state.data.transactions.filter(r=>state.year==='all'||String(r.fiscal_year)===state.year); }
  function selectedAwards() {
    const rows=selectedTx(); const grouped=groupBy(rows,'award_id'); const byId=new Map(state.data.awards.map(r=>[r.award_id,r]));
    return Object.entries(grouped).map(([id,tx])=>({...byId.get(id),award_id:id,recipient_id:tx.at(-1).recipient_id,recipient_name:tx.at(-1).recipient_name,recipient_ids:[...new Set(tx.map(t=>t.recipient_id))],recipient_names:[...new Set(tx.map(t=>t.recipient_name))],description:byId.get(id)?.description||tx.at(-1).description,source_url:byId.get(id)?.source_url||tx.at(-1).source_url,net_obligations:sum(tx,'obligation'),positive_obligations:sum(tx,r=>Math.max(0,r.obligation)),transaction_count:tx.length,first_action:tx.map(r=>r.action_date).sort()[0],last_action:tx.map(r=>r.action_date).sort().at(-1)})).sort((a,b)=>b.positive_obligations-a.positive_obligations);
  }
  function awardsForRecipient(id) {
    const tx=selectedTx().filter(t=>t.recipient_id===id),ids=new Set(tx.map(t=>t.award_id));
    return selectedAwards().filter(a=>ids.has(a.award_id)).map(a=>({...a,full_award_net_obligations:a.net_obligations,attributed_net_obligations:sum(tx.filter(t=>t.award_id===a.award_id),'obligation'),attributed_transaction_count:tx.filter(t=>t.award_id===a.award_id).length,attributed_last_action:tx.filter(t=>t.award_id===a.award_id).map(t=>t.action_date).sort().at(-1)}));
  }
  function recipientRows(rows=selectedTx()) { return Object.entries(groupBy(rows,'recipient_id')).map(([id,tx])=>({recipient_id:id,recipient_name:tx.at(-1).recipient_name,net_obligations:sum(tx,'obligation'),positive_obligations:sum(tx,r=>Math.max(0,r.obligation)),concentration_weight:Math.max(sum(tx,'obligation'),0),awards:new Set(tx.map(r=>r.award_id)).size,transactions:tx.length})).sort((a,b)=>b.concentration_weight-a.concentration_weight); }
  function stats(rows=selectedTx()) {
    const positive=sum(rows,r=>Math.max(0,r.obligation)); const recipients=recipientRows(rows); const concentrationDenominator=sum(recipients,'concentration_weight');
    const competition=rows.reduce((a,r)=>{a[competitionClass(r.competition)]++;return a;},{competed:0,noncompetitive:0,unknown:0});
    return {net:sum(rows,'obligation'),positive,concentrationDenominator,negative:sum(rows,r=>Math.min(0,r.obligation)),transactions:rows.length,awards:new Set(rows.map(r=>r.award_id)).size,recipients:recipients.length,hhi:concentrationDenominator?10000*sum(recipients,r=>(r.concentration_weight/concentrationDenominator)**2):null,top4:concentrationDenominator?sum(recipients.slice(0,4),'concentration_weight')/concentrationDenominator:null,september:positive?sum(rows.filter(r=>String(r.action_date).slice(5,7)==='09'),r=>Math.max(0,r.obligation))/positive:null,competition};
  }
  function competitionClass(value) {
    if (value == null || value === '') return 'unknown';
    const v=String(value).trim().toUpperCase();
    if (['A','D','F','FULL AND OPEN COMPETITION','FULL AND OPEN COMPETITION AFTER EXCLUSION OF SOURCES','COMPETED UNDER SAP'].includes(v)) return 'competed';
    if (['B','C','G','NDO','NOT COMPETED','NOT AVAILABLE FOR COMPETITION','NOT COMPETED UNDER SAP','NON-COMPETITIVE DELIVERY ORDER'].includes(v)) return 'noncompetitive';
    return 'unknown';
  }
  function scope() { return state.year==='all' ? `FY${state.data.years[0]}–${state.data.years.at(-1)}` : `FY${state.year}`; }
  function metric(key,label,value,note) { return `<button class="metric" data-evidence="${key}"><span class="metric-label">${esc(label)}<span class="evidence-mark" aria-hidden="true">↗</span></span><strong class="metric-value">${esc(value)}</strong><span class="metric-note">${esc(note)}</span></button>`; }
  function panelHead(title,subtitle,tag='') { return `<div class="panel-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${tag?`<span class="panel-tag">${esc(tag)}</span>`:''}</div>`; }
  function annualChart() {
    const rows=state.data.years.map(year=>({year,...stats(state.data.transactions.filter(r=>r.fiscal_year===year))}));
    const max=Math.max(...rows.map(r=>r.positive),1); const w=560,h=200,left=60,right=20,top=18,bottom=38,cw=w-left-right,ch=h-top-bottom;
    const bars=rows.map((r,i)=>{const x=left+cw/rows.length*(i+.5),height=r.net/max*ch; return `<g><rect class="bar ${state.year===String(r.year)?'highlight':''}" x="${x-28}" y="${top+ch-Math.max(0,height)}" width="56" height="${Math.max(0,height)}" rx="1"/><text class="value" x="${x}" y="${Math.max(12,top+ch-Math.max(0,height)-9)}" text-anchor="middle">${esc(money(r.net))}</text><text x="${x}" y="${h-12}" text-anchor="middle">FY${r.year}</text></g>`;}).join('');
    const lines=[0,.5,1].map(f=>`<line class="gridline" x1="${left}" y1="${top+ch*(1-f)}" x2="${w-right}" y2="${top+ch*(1-f)}"/><text x="${left-10}" y="${top+ch*(1-f)+3}" text-anchor="end">${esc(money(max*f))}</text>`).join('');
    return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Net obligations by fiscal year: ${esc(rows.map(r=>`FY${r.year}: ${money(r.net,false)}`).join('; '))}">${lines}${bars}</svg>`;
  }
  function competitionViz(s) {
    const total=s.transactions, c=s.competition.competed, n=s.competition.noncompetitive, u=s.competition.unknown, cp=total?c/total:0,np=total?n/total:0;
    return `<div class="competition-layout"><div class="donut" style="background:conic-gradient(var(--green) 0 ${cp*360}deg,#b88f4b ${cp*360}deg ${(cp+np)*360}deg,#dce1d5 ${(cp+np)*360}deg 360deg)" role="img" aria-label="${pct(cp)} of actions report competed status"><span class="donut-label">${pct(cp,0)}<small>REPORTED COMPETED</small></span></div><div class="split-legend"><div class="split-row"><span><i></i>Competed</span><strong>${integer(c)}</strong></div><div class="split-row"><span><i class="amber"></i>Noncompetitive</span><strong>${integer(n)}</strong></div><div class="split-row"><span><i class="neutral"></i>Unknown</span><strong>${integer(u)}</strong></div></div></div><p class="footnote">Denominator: ${integer(total)} transaction actions. Administrative classifications, including modifications. Missing records stay visible.</p>`;
  }
  function flow() {
    const s=stats(),awards=selectedAwards(),recs=recipientRows();
    return `<section class="panel flow-panel">${panelHead('Follow the funding','One agency. Multiple awards. Identifiable recipients.','PRIME CONTRACTS')}<div class="flow-grid"><button class="flow-node primary" data-evidence="flow"><span class="node-title">Awarding agency</span><strong>${esc(state.data.meta.agency||state.data.meta.agency_name||'Selected agency')}</strong><small>${money(s.net)} net obligations</small></button><div class="flow-arrow" aria-hidden="true">→</div><button class="flow-node" data-open-explorer><span class="node-title">Contract awards</span><strong>${integer(s.awards)} distinct awards</strong><small>${integer(s.transactions)} recorded actions ↗</small></button><div class="flow-arrow recipient-arrow" aria-hidden="true">→</div><div class="mini-list">${recs.slice(0,3).map(r=>`<button data-recipient="${esc(r.recipient_id)}" title="Explore ${esc(r.recipient_name)}"><span>${esc(r.recipient_name)}</span><span class="amount">${money(r.net_obligations)} ↗</span></button>`).join('')||'<span class="muted">No recipients in this selection.</span>'}</div></div><div class="panel-footer"><span>Transaction-level obligations. Award summaries are not added across modifications.</span><button class="text-link" data-evidence="flow">Trace the calculation ↗</button></div></section>`;
  }
  function recipientTable(limit=8) {
    const recs=recipientRows(),s=stats();
    return `<div class="table-wrap"><table><thead><tr><th>Recipient</th><th class="number">Net obligations</th><th class="number">Awards</th><th class="number">Positive-net share</th></tr></thead><tbody>${recs.slice(0,limit).map((r,i)=>`<tr><td class="name"><span class="rank">${String(i+1).padStart(2,'0')}</span><button data-recipient="${esc(r.recipient_id)}">${esc(r.recipient_name)}</button></td><td class="number">${money(r.net_obligations)}</td><td class="number">${integer(r.awards)}</td><td class="number"><span class="inline-bar"><i style="width:${s.concentrationDenominator?r.concentration_weight/s.concentrationDenominator*100:0}%"></i></span>${pct(s.concentrationDenominator?r.concentration_weight/s.concentrationDenominator:0)}</td></tr>`).join('')}</tbody></table></div>`;
  }
  function renderOverview() {
    const s=stats(); const link=state.linkage?.summary;
    $('#view-overview').innerHTML=`<div class="section-kicker">${esc(scope())} · The ledger at a glance</div><div class="metrics">${metric('net','Net obligations',money(s.net),`${money(s.negative)} in negative adjustments retained`)}${metric('awards','Contract awards',integer(s.awards),`${integer(s.transactions)} transaction actions`)}${metric('recipients','Identified recipients',integer(s.recipients),'Legal recipients · identifiers before names')}${metric('hhi','Supplier concentration',dec(s.hhi),`HHI / 10,000 · top 4 share ${pct(s.top4)}`)}</div>${flow()}<div class="grid"><section class="panel">${panelHead('A three-year perspective','Net obligations by federal fiscal year','ACTUAL TRANSACTIONS')}${annualChart()}<div class="panel-footer"><span>Fiscal years run October 1 to September 30.</span><button class="text-link" data-evidence="annual">Formula & SQL ↗</button></div></section><section class="panel competition-panel">${panelHead('Competition, as reported','Source classifications by action')}${competitionViz(s)}<div class="panel-footer"><span>No inferred bids or tender scores.</span><button class="text-link" data-evidence="competition">Inspect evidence ↗</button></div></section></div><div class="callout"><span class="callout-icon" aria-hidden="true">⋈</span><div><h3>Would a different entity match change the answer?</h3><p>${esc(link?.interpretation||'Explore supplier identity uncertainty separately from the administrative identifiers in the source. A similar name does not justify merging two recipients.')}</p></div><button class="text-link" data-tab="uncertainty">Test the conclusion ↗</button></div><section class="panel">${panelHead('Where the commitments go','Recipients ordered by positive-net balances. Large totals are not a risk ranking.')} ${recipientTable()}<div class="panel-footer"><span>${integer(s.recipients)} recipients in this selection · shares use positive recipient net balances</span><button class="text-link" data-evidence="top">Formula & SQL ↗</button></div></section>${researchFindings()}`;
  }
  function renderExplorer() {
    const awards=selectedAwards();
    if (state.selectedAward&&!awards.some(a=>a.award_id===state.selectedAward)) state.selectedAward=null;
    let detail='';
    if(state.selectedAward) detail=awardDetail(state.selectedAward);
    else if(state.selectedRecipient) detail=recipientDetail(state.selectedRecipient);
    const candidates=state.selectedRecipient?awardsForRecipient(state.selectedRecipient):awards;
    const filtered=candidates.filter(r=>`${r.award_id} ${r.piid||''} ${r.recipient_name} ${r.description}`.toLowerCase().includes(state.search.toLowerCase()));
    const pages=Math.max(1,Math.ceil(filtered.length/state.pageSize));state.page=Math.min(state.page,pages);
    const shown=filtered.slice((state.page-1)*state.pageSize,state.page*state.pageSize);
    $('#view-explorer').innerHTML=`${detail}<section class="panel">${panelHead(state.selectedRecipient?'Awards for this recipient':'The award ledger',state.selectedRecipient?'Amounts shown are actions attributed to this recipient. Open an award for its complete selected-window history.':'Select an award to follow its modifications and source records.')}<div class="table-controls"><label class="search"><span class="sr-only" hidden>Search award ledger</span><input aria-label="Search awards or recipients" id="award-search" type="search" placeholder="Search awards, recipients, descriptions…" value="${esc(state.search)}"></label>${state.selectedRecipient?'<button class="button secondary small" data-clear-recipient>All recipients</button>':''}<span class="result-count">${integer(filtered.length)} awards</span></div><div class="table-wrap"><table><thead><tr><th>Award / recipient</th><th class="number">Net obligations</th><th class="number">${state.selectedRecipient?'Attributed actions':'Actions'}</th><th>Latest action</th><th></th></tr></thead><tbody>${shown.map(a=>`<tr><td class="name"><button data-award="${esc(a.award_id)}">${esc(a.piid||a.award_id)}</button><div class="muted" style="font-size:9px;margin-top:4px">${state.selectedRecipient?'Latest award recipient: ':''}${esc(a.recipient_name)}${a.recipient_ids?.length>1?' · recipient changed':''}</div></td><td class="number ${(a.attributed_net_obligations??a.net_obligations)<0?'negative-text':''}">${money(a.attributed_net_obligations??a.net_obligations)}${a.attributed_net_obligations!=null&&a.recipient_ids?.length>1?`<div class="muted" style="font:8px var(--sans);margin-top:4px">Full award: ${money(a.full_award_net_obligations)}</div>`:''}</td><td class="number">${integer(a.attributed_transaction_count??a.transaction_count)}</td><td class="no-wrap muted">${fmtDate(a.attributed_last_action??a.last_action)}</td><td><button class="text-link" data-award="${esc(a.award_id)}" aria-label="Explore award ${esc(a.piid||a.award_id)}">↗</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No awards match this search. Try a shorter recipient name or clear the search.</div></td></tr>'}</tbody></table></div><div class="pagination"><span>Page ${state.page} of ${pages}</span><button class="button secondary small" data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="Previous page">←</button><button class="button secondary small" data-page="${state.page+1}" ${state.page===pages?'disabled':''} aria-label="Next page">→</button></div><div class="panel-footer"><span>Amounts cover actions in ${esc(scope())}, not the lifetime award ceiling.</span><button class="text-link" data-evidence="flow">Trace the ledger ↗</button></div></section>`;
  }
  function awardDetail(id) {
    const a=selectedAwards().find(a=>a.award_id===id);if(!a)return '';
    const tx=selectedTx().filter(r=>r.award_id===id).sort((a,b)=>String(a.action_date).localeCompare(String(b.action_date))||String(a.transaction_id).localeCompare(String(b.transaction_id)));let cumulative=0;
    return `<section class="panel" style="margin-bottom:24px"><div class="detail-heading"><p class="eyebrow">AWARD DETAIL · ${esc(a.piid||a.award_id)}</p><h2>${esc(a.piid||a.award_id)}</h2><p>Latest reported recipient: <strong>${esc(a.recipient_name)}</strong>${a.recipient_names?.length>1?` · Recipient history: ${esc(a.recipient_names.join(' → '))}`:''}</p><p>${esc(a.description)}</p></div><div class="detail-stats"><div><span>Net in selection</span><strong>${money(a.net_obligations)}</strong></div><div><span>Recorded actions</span><strong>${integer(tx.length)}</strong></div><div><span>Recipient</span><button class="text-link" data-recipient="${esc(a.recipient_id)}">View entity ↗</button></div><div><span>Official evidence</span><a class="text-link" href="${safeUrl(a.source_url)}" target="_blank" rel="noopener">USAspending award ↗</a></div></div><div class="grid equal"><div><h3 style="font-size:12px;margin-bottom:20px">Modification timeline</h3><ol class="timeline">${tx.slice(0,60).map(t=>{cumulative+=t.obligation;return `<li class="${t.obligation<0?'deobligation':''}"><div class="timeline-top"><span class="timeline-date">${fmtDate(t.action_date)}</span><strong class="timeline-amount ${t.obligation<0?'negative-text':''}">${money(t.obligation,false)}</strong></div><p>${esc(get(t,['modification_number','modification_id'],'Recorded action'))} · ${esc(t.recipient_name)} · Cumulative in selection: ${money(cumulative)}</p><div class="timeline-id">${esc(t.transaction_id)}</div></li>`;}).join('')}</ol>${tx.length>60?`<p class="footnote">Showing the first 60 of ${tx.length} actions. Export the dossier for all selected transaction records.</p>`:''}</div><div class="prose"><h3>What this history shows</h3><p>Each point is one source transaction. Positive obligations increase the recorded commitment; negative obligations reduce it. A modification is not automatically a new award.</p><h3>Competition in these actions</h3>${competitionViz(stats(tx))}<h3>Before drawing a conclusion</h3><p>Continuing work, administrative corrections, option exercises, and closeouts can explain substantial changes. Award values and ceilings may be revised and should not be substituted for transaction obligations.</p><button class="text-link" data-award-evidence="${esc(id)}">Inspect source-to-metric lineage ↗</button></div></div><div class="panel-footer"><span>Cumulative values begin at the first action in the selected cohort, not at award inception.</span><button class="text-link" data-clear-award>Close award detail ↑</button></div></section>`;
  }
  function recipientDetail(id) {
    const rows=selectedTx().filter(r=>r.recipient_id===id),r=recipientRows(rows)[0];if(!r)return '';
    const aliases=[...new Set(rows.map(r=>r.recipient_name))];
    return `<section class="panel" style="margin-bottom:24px"><div class="detail-heading"><p class="eyebrow">RECIPIENT ENTITY · RELIABLE IDENTIFIER FIRST</p><h2>${esc(r.recipient_name)}</h2><p class="mono break">${esc(r.recipient_id)}</p></div><div class="detail-stats"><div><span>Net obligations</span><strong>${money(r.net_obligations)}</strong></div><div><span>Awards</span><strong>${integer(r.awards)}</strong></div><div><span>Actions</span><strong>${integer(r.transactions)}</strong></div></div><p class="footnote">${aliases.length>1?`Observed source names: ${esc(aliases.join(' · '))}.`:'One reported name in this selection.'} Legal-recipient grouping does not imply common ownership. Parent-recipient analysis is a separate view.</p><div class="panel-footer"><button class="text-link" data-tab="uncertainty">Inspect entity uncertainty ↗</button><button class="text-link" data-clear-recipient>All recipients ↑</button></div></section>`;
  }
  function peers() {
    const rows=selectedTx();const groups=Object.entries(groupBy(rows,r=>String(r.naics).slice(0,3))).map(([naics,tx])=>({naics,...stats(tx)})).sort((a,b)=>b.positive-a.positive);
    return `<section class="panel" style="margin-top:24px">${panelHead('Compare procurement peers','Within this agency and fiscal-year selection, grouped by the first three digits of reported NAICS industry.')}<div class="table-wrap"><table><thead><tr><th>NAICS peer group</th><th class="number">Positive obligations</th><th class="number">Recipients</th><th class="number">HHI</th><th class="number">Competed actions</th></tr></thead><tbody>${groups.slice(0,12).map(r=>`<tr><td>${esc(r.naics)}</td><td class="number">${money(r.positive)}</td><td class="number">${integer(r.recipients)}</td><td class="number">${dec(r.hhi)}</td><td class="number">${pct(r.transactions?r.competition.competed/r.transactions:0)}</td></tr>`).join('')}</tbody></table></div><div class="panel-footer"><span>Small or broad groups may not represent substitutable markets.</span><button class="text-link" data-evidence="peers">Definitions & SQL ↗</button></div></section>`;
  }
  function renderUncertainty() {
    const l=state.linkage;
    if(!l){$('#view-uncertainty').innerHTML=`<div class="callout amber"><span class="callout-icon">⋈</span><div><h3>Linkage evidence is not included in this snapshot</h3><p>The source recipient identifiers remain available in the money explorer. No probabilistic merge has been applied.</p></div></div>`;return;}
    const s=l.summary||{},liveQueue=l.queue||[],expQueue=l.experiments?.queue||[],benchmark=l.benchmark||{},real=benchmark.real||{};
    const liveEmpty=!liveQueue.length;
    $('#view-uncertainty').innerHTML=`<div class="section-kicker">Identity is an analytical assumption</div><div class="callout"><span class="callout-icon" aria-hidden="true">✓</span><div><h3>${liveEmpty?'Reliable identifiers anchor this cohort':'Unresolved identities remain separate'}</h3><p>${esc(s.interpretation||'Recipients with reliable identifiers are kept as distinct legal entities. Similar names alone do not trigger a merge.')}</p></div></div><div class="grid equal"><section class="panel">${panelHead('Observed entity grouping','The published cohort uses source identifiers.','REAL DATA')}<div class="detail-stats"><div><span>Identifier coverage</span><strong>${pct(s.identifier_coverage)}</strong></div><div><span>Ambiguous components</span><strong>${integer(s.ambiguous_components??liveQueue.length)}</strong></div></div><p class="footnote">${esc(s.scope||'No reliable identifier is discarded to create apparent uncertainty in the published analysis.')}</p>${s.observed_hhi!=null?`<div class="uncertainty-band"><span class="range-label">${dec(s.lower_hhi??s.observed_hhi,1)}</span><div class="range-track"><div class="range-fill" style="left:45%;right:45%"></div><div class="range-mid" style="left:50%"></div></div><span class="range-label">${dec(s.upper_hhi??s.observed_hhi,1)}</span></div><div class="small-label">${s.lower_hhi===s.upper_hhi?'Same HHI under all admissible observed identity states.':'HHI interval across admissible observed identity states.'} Full cohort scope.</div>`:''}</section><section class="panel">${panelHead('What is being tested?','A decision-sensitive review policy','RESEARCH WORKFLOW')}<p class="lede">Review the ambiguity<br>that could change a decision.</p><p class="footnote">The experiment masks reliable identifiers, predicts linkage from permitted features, samples consistent entity partitions, and compares review policies under equal budgets. It tests identity resolution and decision stability. It does not test fraud detection.</p><button class="text-link" data-linkage-method>Read the experimental method ↗</button></section></div><section class="panel" style="margin-bottom:24px">${panelHead('Operational review queue',`${liveQueue.length} unresolved source-identity components`,'OBSERVED COHORT')}${liveEmpty?'<div class="empty">No unresolved identity components in the observed cohort.<br><span class="small-label">The review experiment below deliberately masks identifiers. Those ambiguities are experimental.</span></div>':liveQueue.map((q,i)=>queueCard(q,i,false)).join('')}</section>${groupingSensitivity()}<div class="callout amber"><span class="callout-icon">i</span><div><h3>Small, relatively easy held-out identity test</h3><p>The real-record test contains ${integer(real.split?.test?.records)} observations from ${integer(real.split?.test?.entities)} UEIs, with only ${integer(real.split?.test?.positive_pairs)} positive pairs. Exact and normalized names already achieve the same test precision and recall as the probabilistic methods. These results do not establish superiority on naturally missing identifiers or misspelled names.</p></div></div>${renderBenchmark(real,'Held-out identifier-backed benchmark','REAL RECORDS · IDENTIFIERS MASKED')}${renderPolicies(l.experiments)}${expQueue.length?`<div class="section-kicker">Research sandbox · identifiers deliberately masked</div><div class="callout amber"><span class="callout-icon" aria-hidden="true">i</span><div><h3>These are experimental identity decisions</h3><p>Known source identifiers are hidden from matching features. This research queue uses ${integer(l.experiments?.records)} held-out observation records, a subset whose HHI differs from the full portfolio. The original records remain resolved in the published warehouse. Each choice previews one conditional resolution over consistent partitions. Selecting another clears the prior preview. These previews do not edit the source data.</p></div></div>${expQueue.map((q,i)=>queueCard(q,i,true)).join('')}`:''}${benchmark.synthetic?renderBenchmark(benchmark.synthetic,'Synthetic perturbation check','SYNTHETIC · NOT REAL-DATA FINDINGS'):''}${l.synthetic_experiments?`<div class="callout amber"><span class="callout-icon">!</span><div><h3>A collapsed scenario range can still be wrong</h3><p>In the synthetic stress test, all three policies retain about 42.741 HHI points of absolute error after five reviews, even when scenario width reaches zero. Candidate support excludes ${integer(l.synthetic_experiments.unsupported_reference_links)} reference links. This is a failure mode, not a policy win: narrow model support does not guarantee the true grouping is represented.</p></div></div>${renderPolicies(l.synthetic_experiments,'Synthetic review-policy stress test','SYNTHETIC · PERTURBED NAMES')}`:''}`;
  }
  function renderBenchmark(b,title,label) {
    if(!b||!b.methods?.length)return '';
    const limit=Array.isArray(b.limitations)?b.limitations.join(' '):b.limitations||'';
    return `<section class="panel" style="margin-bottom:24px">${panelHead(title,typeof b.split==='string'?b.split:`${integer(b.split?.test?.pairs)} held-out test pairs · ${integer(b.split?.test?.positive_pairs)} positive pairs · identifiers excluded from features`,label)}<div class="table-wrap"><table><thead><tr><th>Matching method</th><th class="number">Precision</th><th class="number">Recall</th><th class="number">Brier score ↓</th><th class="number">Calibration ECE ↓</th><th class="number">Error cost</th><th class="number">False merges</th><th class="number">Missed links</th></tr></thead><tbody>${b.methods.map(m=>`<tr><td>${esc(m.method)}</td><td class="number">${pct(m.precision)}</td><td class="number">${pct(m.recall)}</td><td class="number">${dec(m.brier,6)}</td><td class="number">${dec(m.ece,6)}</td><td class="number">${dec(m.error_cost)}</td><td class="number">${integer(m.false_positives)}</td><td class="number">${integer(m.false_negatives)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">${esc(limit)}</p><div class="panel-footer"><span>Brier measures probability error; ECE measures calibration error. Cost = 10 × false merges + missed links, an illustrative preference. Full calibration bins and intervals are in the evidence.</span><button class="text-link" data-linkage-method>Definitions & limitations ↗</button></div></section>`;
  }
  function renderPolicies(exp,title='Does targeted review help?',tag='EXPERIMENT') {
    if(!exp?.policies?.length)return '';
    const limit=Array.isArray(exp.limitations)?exp.limitations.join(' '):exp.limitations||'';
    return `<section class="panel" style="margin-bottom:24px">${panelHead(title,`Equal-budget policies · ${integer(exp.records)} identifier-masked observations · ${integer(exp.replicates)} simulation replicates`,tag)}<div class="table-wrap"><table><thead><tr><th>Review policy</th><th class="number">Budget</th><th class="number">HHI absolute error ↓</th><th class="number">Rank correlation ↑</th><th class="number">Scenario width</th></tr></thead><tbody>${[...exp.policies].sort((a,b)=>a.budget-b.budget||a.policy.localeCompare(b.policy)).map(p=>`<tr><td>${esc(titleCase(p.policy))}</td><td class="number">${integer(p.budget)}</td><td class="number">${dec(p.hhi_absolute_error,2)}</td><td class="number">${dec(p.ranking_stability,3)}</td><td class="number">${dec(p.hhi_scenario_width,3)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">${esc(exp.scope||'')} ${esc(limit)}</p><div class="panel-footer"><span>Means across simulation replicates. Rank correlation: Kendall τ against identifier-backed reference; scenario width is model support, not confidence.</span><button class="text-link" data-linkage-method>Policy experiment evidence ↗</button></div></section>`;
  }
  function scenarioRanking(scenario,title) {
    if(!scenario?.top_three?.length)return '';
    return `<div><span class="small-label">${esc(title)}</span><ol class="decision-ranking">${scenario.top_three.map(t=>`<li><span>${esc((t.names||[]).join(' + '))}</span>${t.positive_net_exposure_share!=null?`<strong>${pct(t.positive_net_exposure_share)}</strong>`:''}</li>`).join('')}</ol><p class="small-label">${esc(scenario.ranking_label||'Most frequent top-three grouping among sampled consistent partitions, conditional on this pair choice.')} ${scenario.modal_partition_sample_support!=null?`Modal partition sample support: ${pct(scenario.modal_partition_sample_support)} of ${integer(scenario.scenario_count)} conditional worlds.`:''}</p></div>`;
  }
  function queueCard(q,i,experimental) {
    const id=String(q.id||`${experimental?'exp':'live'}-${i}`),choice=state.scenario[id]||'unresolved'; const separate=q.separate||{},merged=q.merged||{};const selected=choice==='merged'?merged:choice==='separate'?separate:null;
    const scenarioText=selected?`<strong>${choice==='merged'?'Same entity':'Keep separate'}</strong> · conditional mean HHI ${dec(selected.hhi,2)}${selected.top_recipient_share!=null?` · top recipient share ${pct(selected.top_recipient_share)}`:''}${selected.rank!=null?` · review rank ${esc(selected.rank)}`:''}. ${esc(selected.conclusion||'This is a local scenario, not an adjudication.')}`:`Unresolved · conditional mean HHI if kept separate: ${dec(separate.hhi,2)}; if merged: ${dec(merged.hhi,2)}. ${esc(q.decision?.interpretation||'Review the evidence before resolving identity.')}`;
    return `<article class="queue-card"><div class="queue-head"><div><p>${experimental?'MASKED-IDENTIFIER EXPERIMENT':'OBSERVED COMPONENT'} · ${esc(id)}</p><h3>${esc((q.names||[]).join(' ↔ ')||q.name||'Ambiguous recipient group')}</h3></div><span class="badge amber">${q.probability!=null?pct(q.probability,0)+' estimated match':'Probability unavailable'}</span></div><p class="reason">${esc(q.decision?.survives_pair_alternatives?'These two conditional identity alternatives change the concentration estimate, while the selected top-three review membership remains stable.':q.reason||'Identity evidence requires review.')} ${esc(q.probability_label||'')}</p><div class="scenario-controls" role="group" aria-label="Preview entity grouping for ${esc(id)}"><button class="scenario-btn ${choice==='unresolved'?'selected':''}" data-scenario-id="${esc(id)}" data-scenario="unresolved" aria-pressed="${choice==='unresolved'}">Leave unresolved</button><button class="scenario-btn ${choice==='merged'?'selected':''}" data-scenario-id="${esc(id)}" data-scenario="merged" aria-pressed="${choice==='merged'}">Preview same entity</button><button class="scenario-btn ${choice==='separate'?'selected':''}" data-scenario-id="${esc(id)}" data-scenario="separate" aria-pressed="${choice==='separate'}">Preview separate entities</button></div><div class="scenario-results" aria-live="polite">${scenarioText}</div>${q.decision?`<div class="decision-summary"><span class="badge ${q.decision.survives_pair_alternatives?'':'amber'}">${q.decision.survives_pair_alternatives?'Review membership survives':'Review membership changes'}</span><p>${esc(q.decision.label)}</p><p class="footnote">${esc(q.decision.interpretation||'')} ${esc(q.decision.support_note||'')}</p></div><div class="decision-comparison">${scenarioRanking(separate,'IF KEPT SEPARATE')}${scenarioRanking(merged,'IF THE SAME ENTITY')}</div>`:''}<div class="panel-footer"><span>One conditional preview at a time. All other components stay unresolved.</span><button class="text-link" data-queue-evidence="${esc(id)}" data-experimental="${experimental}">Inspect identity evidence ↗</button></div></article>`;
  }
  function renderCases() {
    let cases=state.cases;
    if(!cases.length){$('#view-cases').innerHTML=`<div class="empty">Case-study evidence is not included in this snapshot. Explore the transaction ledger and methodology.</div>`;return;}
    $('#view-cases').innerHTML=`<div class="case-grid">${cases.map((c,i)=>`<article class="case-card"><div class="case-number">${String(i+1).padStart(2,'0')}</div><span class="eyebrow">${esc(c.theme||'SOURCE-TRACEABLE ANALYSIS')}</span><h2>${esc(c.title)}</h2><p>${esc(c.question||c.finding||'')}</p>${c.metric_value!=null?`<div class="case-stat">${esc(c.metric_value)}</div><div class="case-stat-label">${esc(c.metric_label||'')}</div>`:''}<button class="text-link" data-case="${esc(c.id||i)}">Open the working paper ↗</button></article>`).join('')}</div><div class="callout amber"><span class="callout-icon" aria-hidden="true">i</span><div><h3>A finding is the beginning of a question</h3><p>Cases retain their fixed FY2022–FY2024 cohort regardless of the explorer filter. Each case is descriptive. Spend concentration, low competition, or year-end timing can have ordinary explanations. Original award evidence and uncertainty belong alongside the headline.</p></div></div>${peers()}${statisticalWorkingPaper()}`;
  }
  function researchFindings() {
    const r=state.reports;if(!r)return '';const d=r.positive_transaction_distribution||{},o=r.overview||{},miss=state.data.missingness||{};
    return `<div class="section-kicker" style="margin-top:28px">Research working papers · full FY2022–FY2024 cohort</div><div class="grid equal"><section class="panel">${panelHead('A long tail of commitments','Positive actions, separated from negative and zero adjustments.')}<div class="detail-stats"><div><span>Median positive action</span><strong>${money(d.median)}</strong></div><div><span>99th percentile</span><strong>${money(d.p99)}</strong></div></div><p class="footnote">The largest 1% of positive actions account for ${pct(d.top_one_percent_share)} of ${money(o.positive)} in gross positive obligations. Denominator: ${integer(d.n_positive)} positive actions. A few large actions can dominate a mean or a timing pattern.</p><div class="panel-footer"><span>Large amounts are not a misconduct indicator.</span><button class="text-link" data-report-evidence="distribution">Formula & evidence ↗</button></div></section><section class="panel">${panelHead('What the fields cannot tell us','Missing values remain part of the denominator.')}<div class="table-wrap"><table><thead><tr><th>Source field</th><th class="number">Missing / all actions</th><th class="number">Missing share</th></tr></thead><tbody>${[['Recipient UEI',miss.uei_missing??0],['Competition',miss.competition_missing??o.missing_competition],['Number of offers',miss.offers_missing??o.missing_offers],['Reported parent UEI',miss.parent_missing??o.missing_parent]].map(([label,n])=>`<tr><td>${esc(label)}</td><td class="number">${integer(n)} / ${integer(o.transactions)}</td><td class="number">${pct(n/o.transactions)}</td></tr>`).join('')}</tbody></table></div><div class="panel-footer"><span>Bidder identities and bid prices are unavailable.</span><button class="text-link" data-report-evidence="missingness">Inspect missingness ↗</button></div></section></div>`;
  }
  function groupingSensitivity() {
    const r=state.reports;if(!r?.entity_grouping_sensitivity)return '';
    return `<section class="panel" style="margin-bottom:24px">${panelHead('A second grouping question: reported parents','Legal-recipient identity and reported corporate grouping are different assumptions.','REAL DATA · SENSITIVITY')}<div class="table-wrap"><table><thead><tr><th>Grouping convention</th>${state.data.years.map(y=>`<th class="number">FY${y} HHI</th>`).join('')}</tr></thead><tbody>${r.entity_grouping_sensitivity.map(g=>`<tr><td>${esc({recipient_uei:'Recipient UEI',parent_reported_on_action:'Parent reported on each action',latest_observed_parent:'Latest observed parent applied retrospectively'}[g.scenario]||g.scenario)}</td>${state.data.years.map(y=>`<td class="number">${dec(g.annual.find(a=>a.fy===y)?.hhi,1)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="footnote">Parent reports change over time and are not verified ultimate ownership. The contemporaneous-parent convention can split one recipient across reports, so HHI can move in either direction. The retrospective convention uses later information and is a sensitivity scenario, not the historical default.</p><div class="panel-footer"><span>Same signed transaction obligations; different entity-grouping assumptions.</span><button class="text-link" data-report-evidence="grouping">Inspect formulas & source ↗</button></div></section>`;
  }
  function statisticalWorkingPaper() {
    const r=state.reports;if(!r)return '';
    return `<section class="panel" style="margin-top:24px">${panelHead('Year-end timing and award mix','Whole-award resampling tests composition sensitivity.','FULL COHORT RESEARCH')}<div class="table-wrap"><table><thead><tr><th>Fiscal year</th><th class="number">Observed September share</th><th class="number">Resampled 2.5th percentile</th><th class="number">Resampled 97.5th percentile</th><th class="number">Awards</th></tr></thead><tbody>${(r.september_award_mix_bootstrap||[]).map(b=>`<tr><td>FY${b.fy}</td><td class="number">${pct(r.annual.find(a=>a.fy===b.fy)?.september_positive_share)}</td><td class="number">${pct(b.p025)}</td><td class="number">${pct(b.p975)}</td><td class="number">${integer(b.awards)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">${esc(r.bootstrap_note)} This is an observed census within the source cohort. The interval describes the effect of resampling its award mix; it is not uncertainty about the recorded total and does not establish a cause.</p><div class="panel-footer"><span>Denominator: positive obligations in each fiscal year.</span><button class="text-link" data-report-evidence="timing">Inspect statistical working paper ↗</button></div></section>`;
  }
  function reportEvidence(topic) {
    const r=state.reports||{};const definitions={distribution:{title:'Heavy-tailed action obligations',formula:'Restrict to obligation > 0. Compute median, 90th and 99th percentiles; sort positive actions descending and sum the largest ceil(0.01 × count) values / total positive obligations.',sql:'SELECT QUANTILE_CONT(obligation,0.5) AS median,\n QUANTILE_CONT(obligation,0.9) AS p90,\n QUANTILE_CONT(obligation,0.99) AS p99\nFROM fact_transactions WHERE obligation > 0;',evidence:r.positive_transaction_distribution,limit:'Values describe action sizes, not contract performance or ultimate cash payments. Specialized services or planned large purchases can produce a heavy tail.'},missingness:{title:'Source-field missingness',formula:'Missing field action count / all 4,683 in-scope action records. Source NA/null values remain missing rather than becoming zero offers.',sql:'SELECT COUNT(*) AS actions,\n COUNT(*) FILTER (WHERE offers_received IS NULL) AS missing_offers,\n COUNT(*) FILTER (WHERE competition_code IS NULL) AS missing_competition\nFROM fact_transactions;',evidence:state.data.missingness,limit:'Missing offers do not mean no offers. The administrative competition classification does not expose bidder identities or bid prices.'},grouping:{title:'Entity-grouping sensitivity',formula:'For each fiscal year and grouping scenario, sum signed obligations by entity group; use max(group net balance,0) / sum(max(group net balance,0)) as the HHI shares.',sql:'-- Source executable report: civicledger/reports.py\n-- Source warehouse: sql/01_warehouse.sql\n-- Compare recipient UEI, contemporaneously reported parent,\n-- and latest observed parent applied retrospectively.',evidence:r.entity_grouping_sensitivity,limit:'The source reports parent recipients, not verified beneficial ownership. Parent reports change over time. Retrospective grouping deliberately uses later information and is not the historical default.'},timing:{title:'September award-mix resampling',formula:'Within each fiscal year, resample whole awards with replacement 1,000 times; recompute September positive obligations / all positive obligations. Report 2.5th and 97.5th percentiles of the resampled statistics.',sql:'SELECT fiscal_year, award_id,\n SUM(GREATEST(obligation,0)) AS positive,\n SUM(CASE WHEN MONTH(action_date)=9 THEN GREATEST(obligation,0) ELSE 0 END) AS september\nFROM fact_transactions GROUP BY fiscal_year,award_id;\n-- Whole-award resampling: civicledger/reports.py; seed 20261025.',evidence:r.september_award_mix_bootstrap,limit:r.bootstrap_note}};
    const d=definitions[topic];if(!d)return;
    openDialog(d.title,`<h3>Scope</h3><p>Entire NRC contract cohort, FY2022–FY2024. These research results retain the full-cohort scope independently of the explorer's fiscal-year selection.</p><h3>Formula & denominator</h3><p>${esc(d.formula)}</p><h3>SQL & reproduction</h3><pre>${esc(d.sql)}</pre><p><a href="https://github.com/nazeeh111/civicledger/blob/main/civicledger/reports.py" target="_blank" rel="noopener">Executable statistical report ↗</a></p><h3>Retained analytical result</h3><pre>${esc(JSON.stringify(d.evidence,null,2))}</pre><h3>Interpretation & benign explanations</h3><p class="evidence-note">${esc(d.limit)}</p>`);
  }
  function renderMethods() {
    const m=state.data.meta;
    $('#view-methods').innerHTML=`<div class="two-col"><section class="panel prose">${panelHead('The evidence contract','A bounded cohort with explicit limits.')}<p class="lede">Every total has a grain.<br>Every conclusion has a limit.</p><p>The warehouse separates transaction facts from award summaries and recipient, agency, and classification dimensions. All spending amounts here come from individual obligation transactions. Repeated award summary totals are never added across modifications.</p><h3>Scope</h3><p>${esc(m.scope||m.description||'Federal prime contract actions for the selected agency and fiscal years.')} Fiscal years: ${esc(state.data.years.join(', '))}. Retrieved ${esc(fmtDate(m.retrieved_at||m.retrieval_date||m.snapshot_date))}.</p><h3>Reproducibility</h3><p>The release includes a minimized public snapshot, raw-response checksums, retrieval metadata, acquisition code, transformation SQL, validation checks, and original source identifiers. Full-field raw archives remain local because they can contain unnecessary personal details. Source data can be revised after retrieval; this analysis describes the retained snapshot.</p><button class="text-link" data-provenance>Inspect filters, counts & provenance ↗</button><h3>Meaningful comparisons</h3><p>Peer comparisons use the same agency, selected fiscal year, and reported NAICS industry. The labels remain broad. Statistical associations do not establish a cause or identify misconduct.</p><h3>What remains unavailable</h3><p>USAspending is not an Open Contracting Data Standard (OCDS) tender feed. Tender documents, bid submission dates, complete bidder lists, tender periods, disqualification reasons, and adjudicated misconduct labels are unavailable in this cohort. No indicator requiring those fields is calculated.</p><h3>Privacy</h3><p>The public explorer contains organizational identifiers and procurement facts. Unnecessary personal contact information is removed from descriptions in the public data export. The source government record remains linked.</p></section><section class="panel">${panelHead('Read the source','Implementation, definitions, and methodological foundations.')}<ul class="source-list"><li><a href="https://api.usaspending.gov/" target="_blank" rel="noopener">USAspending API ↗</a><small>Official public spending data and endpoint documentation.</small></li><li><a href="https://github.com/fedspendingtransparency/usaspending-api" target="_blank" rel="noopener">USAspending implementation ↗</a><small>Source contracts, field semantics, filters, and aggregation behavior.</small></li><li><a href="https://github.com/moj-analytical-services/splink" target="_blank" rel="noopener">Splink ↗</a><small>Probabilistic record linkage and comparison features.</small></li><li><a href="https://github.com/open-contracting/cardinal-rs" target="_blank" rel="noopener">Open Contracting Cardinal ↗</a><small>Indicator prerequisites. Missing tender fields remain unavailable.</small></li><li><a href="https://www.open-contracting.org/resources/red-flags-in-public-procurement-a-guide-to-using-data-to-detect-and-mitigate-risks/" target="_blank" rel="noopener">Open Contracting methodology ↗</a><small>Context and evidence required when interpreting procurement patterns.</small></li><li><a href="https://github.com/evidence-dev/evidence" target="_blank" rel="noopener">Evidence SQL reporting ↗</a><small>SQL-first analytical reporting design reference.</small></li></ul></section></div><div class="section-kicker" style="margin-top:26px">Read the numbers correctly</div><div class="method-grid"><section class="method-card"><h3>Obligations are commitments</h3><p>An obligation is a binding promise to pay. An outlay is cash disbursed. An award ceiling is a possible maximum. These quantities are different and must not be added together.</p></section><section class="method-card"><h3>Negative values belong in the ledger</h3><p>Deobligations reduce a commitment. They can result from closeouts, changed requirements, or corrections. They remain in net totals. Concentration uses positive-net supplier balances so shares stay nonnegative.</p></section><section class="method-card"><h3>Legal recipient and parent are different</h3><p>A UEI identifies a registered legal entity. A parent can own several recipients. Legal-entity and reported-parent groupings answer different questions; similar names alone are insufficient evidence of common ownership.</p></section><section class="method-card"><h3>Competition is an administrative field</h3><p>Reported competition categories are not a full record of bids. Modifications can inherit original award classifications. Missing fields remain unknown, and legitimate exceptions can explain noncompetitive awards.</p></section></div><section class="panel" style="margin-top:24px">${panelHead('Metric working papers','Select a definition to inspect its SQL, denominator, evidence, and interpretation.')}<div class="table-wrap"><table><thead><tr><th>Metric</th><th>Definition</th><th></th></tr></thead><tbody>${Object.entries(metricDefs).map(([key,d])=>`<tr><td>${esc(d.title)}</td><td class="muted">${esc(d.formula)}</td><td><button class="text-link" data-evidence="${key}" aria-label="Inspect ${esc(d.title)}">↗</button></td></tr>`).join('')}</tbody></table></div></section>`;
  }
  function showEvidence(key) {
    const d=metricDefs[key];if(!d)return;const s=stats();
    let value={net:money(s.net,false),awards:integer(s.awards),recipients:integer(s.recipients),hhi:dec(s.hhi,3),yearend:pct(s.september),competition:`${integer(s.competition.competed)} / ${integer(s.transactions)} actions report competition`,top:`Top four share: ${pct(s.top4)}`,flow:`${integer(s.transactions)} transactions → ${integer(s.awards)} awards → ${integer(s.recipients)} recipients`}[key];
    const sourceKey={net:'net_obligations',awards:'award_count',yearend:'september_share'}[key]||key; const supplied=state.data.metrics?.[sourceKey]||{};
    const displayedSql=d.sql.replaceAll('WHERE fiscal_year = :fiscal_year',state.year==='all'?'WHERE fiscal_year BETWEEN 2022 AND 2024':`WHERE fiscal_year = ${Number(state.year)}`);
    openDialog(d.title,`<h3>Selected result · ${esc(scope())}</h3><p>${esc(value||'See the corresponding table or chart.')}</p><h3>Formula & denominator</h3><p>${esc(key==='hhi'&&state.year==='all'?d.formula:(supplied.formula||d.formula))}</p><h3>Executable SQL pattern</h3><pre>${esc(displayedSql)}</pre><p class="footnote">${esc(supplied.source_sql?`Warehouse query: ${supplied.source_sql}. `:'')}The selected cohort contains ${integer(s.transactions)} action records. These transparent query patterns correspond to the release warehouse; the complete executable model files ship with the source.</p><h3>Evidence</h3><p>Source: <a href="https://api.usaspending.gov/" target="_blank" rel="noopener">USAspending API</a>. Snapshot: ${esc(fmtDate(state.data.meta.retrieved_at||state.data.meta.snapshot_date))}. Agency: ${esc(state.data.meta.agency||state.data.meta.agency_name)}.</p><button class="text-link" data-provenance>Inspect exact source filters & provenance ↗</button><h3>Interpretation & possible benign explanations</h3><p class="evidence-note">${esc([supplied.interpretation,supplied.benign_explanation].filter(Boolean).join(' ')||d.caveat)}</p>`);
  }
  function openDialog(title,body) {$('#evidence-title').textContent=title;$('#evidence-body').innerHTML=body;const d=$('#evidence-dialog');if(!d.open)d.showModal();}
  function provenance() {
    const m=state.data.meta;
    openDialog('Snapshot & source lineage',`<h3>Cohort</h3><p>${esc(m.agency||m.agency_name)} · ${esc(m.scope||m.description||'Prime contract transactions')} · ${esc(state.data.years.map(y=>`FY${y}`).join(', '))}</p><h3>Exact filters</h3><pre>${esc(JSON.stringify(m.filters||m.request||{},null,2))}</pre><h3>Snapshot metadata</h3><pre>${esc(JSON.stringify({...m,filters:undefined,request:undefined},null,2))}</pre><h3>Published row counts</h3><p>${integer(state.data.transactions.length)} transaction facts · ${integer(state.data.awards.length)} distinct awards · ${integer(recipientRows(state.data.transactions).length)} reliable recipient groups.</p><h3>What can change</h3><p class="evidence-note">Government reporting can be corrected after retrieval. Reconciliation uses the same snapshot filters and distinguishes transaction totals from award summaries. Replay the retained snapshot for the published result; fetch anew to study revisions.</p>`);
  }
  function awardEvidence(id) {
    const tx=selectedTx().filter(t=>t.award_id===id);const a=selectedAwards().find(a=>a.award_id===id);if(!a)return;
    openDialog('Award source-to-metric lineage',`<h3>Evidence identifiers</h3><p class="break">Award: ${esc(id)}<br>Recipient: ${esc(a.recipient_id)}</p><p><a href="${safeUrl(a.source_url)}" target="_blank" rel="noopener">Open the original USAspending award ↗</a></p><h3>Formula</h3><p>Net obligations in selection = sum of ${integer(tx.length)} source transaction obligations, including negative adjustments.</p><pre>SELECT transaction_id, action_date, obligation,\n SUM(obligation) OVER (ORDER BY action_date, transaction_id)\n AS cumulative_in_selection\nFROM fact_transactions\nWHERE award_id = :award_id AND fiscal_year = :fiscal_year;</pre><h3>Constituent source records</h3><pre>${esc(JSON.stringify(tx.map(t=>({transaction_id:t.transaction_id,date:t.action_date,obligation:t.obligation,modification:t.modification_number||null})),null,2))}</pre><h3>Interpretation</h3><p class="evidence-note">The bounded cohort may begin after award inception. Cumulative values shown here are not the full lifetime award value. Option exercises, changed requirements, and closeouts are plausible explanations for adjustments.</p>`);
  }
  function linkageMethod() {
    const l=state.linkage||{},method=l.method||{};
    openDialog('Uncertainty-aware review method',`<h3>Research question</h3><p>Which unresolved entity component is most valuable to review when the decision depends on supplier concentration or a triage ranking?</p><h3>Decision-sensitive review</h3><p>${esc(method.formula||'Estimate the expected reduction in concentration error or ranking uncertainty after resolving a complete ambiguous component. Prioritize that decision impact rather than probability uncertainty alone.')}</p><h3>Cluster consistency</h3><p>Identity is an equivalence relation: if A and B are one entity, and B and C are one entity, A and C cannot be separate. The experiment uses complete, consistent component partitions rather than independent pairwise merge samples.</p><h3>SQL & reproducibility</h3><pre>${esc(method.sql||'SELECT partition_id, recipient_cluster, SUM(obligation) AS net\nFROM plausible_partitions JOIN fact_transactions USING (record_id)\nGROUP BY partition_id, recipient_cluster;')}</pre><h3>Benchmark evidence</h3><pre>${esc(JSON.stringify(l.benchmark?.real||{},null,2))}</pre><h3>Review-policy experiment</h3><pre>${esc(JSON.stringify({...l.experiments,queue:undefined},null,2))}</pre><h3>Limits</h3><p class="evidence-note">${esc(Array.isArray(method.notes)?method.notes.join(' '):method.notes||'Identifier-masked records and synthetic perturbations do not prove performance on naturally unresolved businesses. No adjudicated misconduct labels exist here, and no fraud-detection accuracy is claimed.')}</p>`);
  }
  function queueEvidence(id,experimental) {
    const q=(experimental?state.linkage?.experiments?.queue:state.linkage?.queue)?.find((q,i)=>String(q.id||`${experimental?'exp':'live'}-${i}`)===id);if(!q)return;
    openDialog('Entity review evidence',`<span class="badge ${experimental?'amber':''}">${experimental?'IDENTIFIER-MASKED EXPERIMENT':'OBSERVED COMPONENT'}</span><h3>Records</h3><p>${esc((q.names||[]).join(' ↔ '))}</p><h3>Why review this component?</h3><p>${esc(q.reason||'')} ${esc(q.decision_impact||'')}</p><h3>Probability</h3><p>${q.probability!=null?pct(q.probability):'Unavailable'} · ${esc(q.probability_label||'Estimated, not adjudicated.')}</p><h3>Consistent alternatives</h3><pre>${esc(JSON.stringify({separate:q.separate,merged:q.merged},null,2))}</pre><h3>Original evidence</h3>${(q.evidence||[]).map(e=>`<p><a href="${safeUrl(e.url||e.source_url)}" target="_blank" rel="noopener">${esc(e.label||e.award_id||'Source record')} ↗</a></p>`).join('')||'<p>No direct source links supplied for this component. Use the exported record identifiers.</p>'}<h3>Scope</h3><p class="evidence-note">${esc(q.scope||'')} ${experimental?'Reliable identifiers were deliberately hidden from model features. The published warehouse retains those identifiers.':'No uncertain merge is applied silently.'}</p>`);
  }
  function caseDialog(id) {
    const c=state.cases.find((c,i)=>String(c.id??i)===id);if(!c)return;
    openDialog(c.title,`<p class="eyebrow">SOURCE-TRACEABLE ANALYTICAL CASE</p>${c.question?`<h3>Question</h3><p>${esc(c.question)}</p>`:''}<h3>Finding</h3><p>${esc(c.finding||c.summary||'')}</p>${c.metric_value!=null?`<p class="case-stat">${esc(c.metric_value)}</p><p>${esc(c.metric_label||'')}</p>`:''}<h3>Denominator & scope</h3><p>${esc(c.denominator_text||c.denominator||c.scope||'See exported case working paper.')}</p><h3>Formula</h3><p>${esc(c.formula||'See corresponding SQL.')}</p><h3>SQL</h3><pre>${esc(c.sql||c.query||'See the SQL cookbook in the release repository.')}</pre><h3>Original records</h3>${(c.evidence||[]).map(e=>`<p><a href="${safeUrl(e.url||e.source_url)}" target="_blank" rel="noopener">${esc(e.label||e.award_id||e.transaction_id||'Official evidence')} ↗</a>${e.transaction_id?`<br><span class="mono break">${esc(e.transaction_id)}</span>`:''}</p>`).join('')}<h3>Possible benign explanations</h3><ul>${(c.benign_explanations||c.alternatives||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>What uncertainty changes</h3><p>${esc(c.uncertainty||c.sensitivity||c.conclusion||'These descriptive findings depend on the selected cohort and recipient grouping. Review source context before making a decision.')}</p><p class="evidence-note">${esc(Array.isArray(c.limits)?c.limits.join(' '):c.limits||'This is a descriptive association, not evidence of wrongdoing.')}</p><div style="display:flex;gap:12px;margin-top:20px;flex-wrap:wrap"><button class="button small" data-case-json="${esc(id)}">Download case dossier</button><button class="button secondary small" data-case-memo="${esc(id)}">Download decision memo</button></div>`);
  }
  function download(filename,content,type='application/json') {const b=new Blob([content],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500);toast(`Downloaded ${filename}`);}
  function toast(message) {const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,6500);}
  function dossier(c=null) {
    const tx=c?state.data.transactions:selectedTx().filter(t=>(!state.selectedAward||t.award_id===state.selectedAward)&&(!state.selectedRecipient||t.recipient_id===state.selectedRecipient));
    const selection=c?{fiscal_year:'all',scope:'Fixed case evidence uses the complete FY2022–FY2024 cohort, independent of explorer filters.',case_id:c.id,case_award_id:c.record?.award_id||null,case_transaction_id:c.record?.transaction_id||null}:{fiscal_year:state.year,award_id:state.selectedAward,recipient_id:state.selectedRecipient,view:state.tab};
    return {title:'CIVICLEDGER reproducible case dossier',exported_at:new Date().toISOString(),snapshot:state.data.meta,selection,metrics:stats(tx),definitions:metricDefs,case:c,entity_scenario_previews:state.scenario,entity_scenario_evidence:Object.keys(state.scenario).map(id=>([...(state.linkage?.queue||[]),...(state.linkage?.experiments?.queue||[])]).find(q=>String(q.id)===id)).filter(Boolean),entity_scenario_scope:'One conditional pair preview at a time; all other components remain unresolved. Conditional mean metrics and modal sampled rankings are not a joint resolved partition.',source_records:tx,limitations:['Obligations are commitments, not cash outlays.','Transaction totals are bounded to the retained cohort.','Entity scenario previews are not identity adjudications.','Patterns are descriptive and do not establish misconduct.'],reproduction:{repository:state.data.meta.repository||'https://github.com/nazeeh111/civicledger',raw_manifest:state.data.meta.raw_manifest,filters:state.data.meta.filters}};
  }
  function decisionMemo(c) {
    const record=c.record||{};return `CIVICLEDGER: DECISION MEMO\n${c.title}\n\nSNAPSHOT\n${state.data.meta.agency}; ${state.data.years.map(y=>`FY${y}`).join(', ')}; snapshot ${state.data.meta.snapshot_id||state.data.meta.retrieved_at}.\n\nQUESTION\n${c.question||''}\n\nFINDING\n${c.finding||c.interpretation||''}\n${c.metric_value!=null?`${c.metric_label||'Metric'}: ${c.metric_value}\n`:''}\n\nDENOMINATOR AND SELECTION\n${c.denominator_text||c.denominator||''}\n${c.selection||''}\n\nPOSSIBLE BENIGN EXPLANATIONS\n${(c.benign_explanations||c.alternative_explanations||[]).map(t=>`- ${t}`).join('\n')}\n\nUNCERTAINTY / DECISION\n${c.uncertainty||c.conclusion||'Review source context before any action.'}\n\nREPRODUCE\nFormula: ${c.formula||''}\nSQL: ${c.sql||''}\nSource: ${record.url||(c.evidence||[]).map(e=>e.url||e.source_url).join('\n')}\nAward: ${record.award_id||''}\nTransaction: ${record.transaction_id||''}\n\nLIMITS\nThis is descriptive procurement analysis. It is not evidence of wrongdoing, a fraud classification, or a causal claim. Obligations are commitments rather than outlays. The retained source snapshot can differ from later revisions.\n`;
  }
  function switchTab(tab,updateHash=true) {
    if(!tabs[tab])tab='overview';state.tab=tab;
    $$('.view').forEach(el=>el.hidden=el.id!==`view-${tab}`);
    $$('.nav-link').forEach(el=>{const active=el.dataset.tab===tab;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
    $('#page-title').innerHTML=tabs[tab].title;$('#page-description').textContent=tabs[tab].description;$('#breadcrumb-view').textContent=tabs[tab].label;
    if(updateHash&&location.hash!==`#${tab}`)history.replaceState(null,'',`#${tab}`);
    document.title=`CIVICLEDGER · ${tabs[tab].label}`;
  }
  function render() {renderOverview();renderExplorer();renderUncertainty();renderCases();renderMethods();switchTab(state.tab,false);}
  function navigateExplorer(award=null,recipient=null) {state.selectedAward=award;state.selectedRecipient=recipient;state.page=1;state.search='';renderExplorer();switchTab('explorer');window.scrollTo({top:0,behavior:'smooth'});}
  document.addEventListener('click',event=>{
    const b=event.target.closest('button,a');if(!b)return;
    if(b.dataset.tab){event.preventDefault();switchTab(b.dataset.tab);window.scrollTo({top:0,behavior:'smooth'});}
    else if(b.dataset.evidence){showEvidence(b.dataset.evidence);}
    else if(b.dataset.reportEvidence){reportEvidence(b.dataset.reportEvidence);}
    else if(b.hasAttribute('data-provenance')){provenance();}
    else if(b.hasAttribute('data-close-dialog')){$('#evidence-dialog').close();}
    else if(b.hasAttribute('data-open-explorer')){navigateExplorer();}
    else if(b.dataset.award){navigateExplorer(b.dataset.award,null);}
    else if(b.dataset.recipient){navigateExplorer(null,b.dataset.recipient);}
    else if(b.hasAttribute('data-clear-award')){state.selectedAward=null;renderExplorer();}
    else if(b.hasAttribute('data-clear-recipient')){state.selectedRecipient=null;state.selectedAward=null;state.page=1;renderExplorer();}
    else if(b.dataset.page){state.page=num(b.dataset.page);renderExplorer();}
    else if(b.dataset.awardEvidence){awardEvidence(b.dataset.awardEvidence);}
    else if(b.hasAttribute('data-linkage-method')){linkageMethod();}
    else if(b.dataset.scenarioId){state.scenario={};state.scenario[b.dataset.scenarioId]=b.dataset.scenario;const focusId=b.dataset.scenarioId,focusChoice=b.dataset.scenario;renderUncertainty();const next=$$('.scenario-btn').find(x=>x.dataset.scenarioId===focusId&&x.dataset.scenario===focusChoice);next?.focus({preventScroll:true});}
    else if(b.dataset.queueEvidence){queueEvidence(b.dataset.queueEvidence,b.dataset.experimental==='true');}
    else if(b.dataset.case){caseDialog(b.dataset.case);}
    else if(b.dataset.caseJson){const c=state.cases.find((c,i)=>String(c.id??i)===b.dataset.caseJson);download(`civicledger-${c.id||'case'}-dossier.json`,JSON.stringify(dossier(c),null,2));}
    else if(b.dataset.caseMemo){const c=state.cases.find((c,i)=>String(c.id??i)===b.dataset.caseMemo);download(`civicledger-${c.id||'case'}-memo.txt`,decisionMemo(c),'text/plain');}
  });
  $('#fiscal-year').addEventListener('change',event=>{state.year=event.target.value;state.page=1;state.selectedAward=null;state.selectedRecipient=null;render();});
  document.addEventListener('input',event=>{if(event.target.id==='award-search'){const start=event.target.selectionStart;state.search=event.target.value;state.page=1;renderExplorer();const input=$('#award-search');input.focus();input.setSelectionRange(start,start);}});
  $('#export-dossier').addEventListener('click',()=>{if(!state.data)return;download(`civicledger-${scope().toLowerCase().replace('–','-')}-dossier.json`,JSON.stringify(dossier(),null,2));});
  $('#evidence-dialog').addEventListener('click',event=>{if(event.target===$('#evidence-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
  window.addEventListener('hashchange',()=>switchTab(location.hash.slice(1)||'overview',false));
  async function fetchJSON(file,required=false){try{const r=await fetch(file,{cache:'no-cache'});if(!r.ok)throw new Error(`${file}: HTTP ${r.status}`);return await r.json();}catch(error){if(required)throw error;console.info(`Optional evidence unavailable: ${file}`,error.message);return null;}}
  async function init(){try{
    const [data,linkage,cases,reports]=await Promise.all([fetchJSON('data.json',true),fetchJSON('linkage.json',true),fetchJSON('cases.json',true),fetchJSON('reports.json',true)]);
    state.data=normalise(data);state.linkage=linkage;state.reports=reports;state.cases=(Array.isArray(cases)?cases:cases?.cases||[]).map(c=>{
      const record=c.record||{},isAward=c.id==='portfolio-concentration';
      const metric_value=c.metric_value??(isAward?money(record.net):record.obligation!=null?money(record.obligation):null);
      const metric_label=c.metric_label??(isAward?'net obligations in the observed award':record.obligation<0?'recorded commitment reduction':'positive September action');
      return {...c,metric_value,metric_label,finding:c.finding||c.interpretation,denominator_text:c.denominator_text||(typeof c.denominator==='number'?`${c.id==='deobligation'?integer(c.denominator)+' transaction actions':money(c.denominator,false)+' in cohort positive obligations'}. ${c.selection||''}`:c.denominator),evidence:c.evidence||(record.url?[{award_id:record.award_id,transaction_id:record.transaction_id,url:record.url,label:`${record.piid||record.award_id} · ${record.recipient||'official award'}`}]:[]),benign_explanations:c.benign_explanations||c.alternative_explanations||[]};
    });
    if(!state.data.transactions.length)throw new Error('The published snapshot contains no transactions.');
    const m=state.data.meta;$('#scope-agency').textContent=m.agency||m.agency_name||'Selected agency';$('#scope-description').textContent=`Prime contract actions · ${state.data.years.map(y=>`FY${y}`).join(' / ')}`;$('#scope-foot').textContent='Bounded research cohort. Source records can be revised.';
    $('#fiscal-year').innerHTML=`<option value="all">All 3 years</option>${state.data.years.map(y=>`<option value="${y}">FY ${y}</option>`).join('')}`;
    $('#snapshot-label').textContent=`SNAPSHOT · ${fmtDate(m.retrieved_at||m.snapshot_date)} UTC`;$('#footer-snapshot').textContent=`${integer(state.data.transactions.length)} source actions · ${m.snapshot_id||fmtDate(m.retrieved_at)} UTC`;
    $('#source-repo').href=safeUrl(m.repository||'https://github.com/nazeeh111/civicledger');$('#source-repo').target='_blank';$('#source-repo').rel='noopener';
    state.tab=tabs[location.hash.slice(1)]?location.hash.slice(1):'overview';render();$('#loading').hidden=true;$('#app').hidden=false;
    window.CIVICLEDGER={state,stats,selectedTx,selectedAwards,awardsForRecipient,recipientRows,dossier,metricDefs,competitionClass,normalise,decisionMemo};
  }catch(error){$('#loading').innerHTML=`<span class="loading-mark" aria-hidden="true">▦</span><h1>Evidence unavailable</h1><p>The source snapshot could not be loaded. Please reload the page or inspect the release repository.</p><p class="error-detail">${esc(error.message)}</p><a class="button secondary" href="https://github.com/nazeeh111/civicledger" target="_blank" rel="noopener">Open source repository ↗</a>`;$('#export-dossier').disabled=true;console.error(error);}}
  init();
})();
